1	package numeric
2	
3	import (
4		"fmt"
5		"os"
6		"sync"
7		"sync/atomic"
8		"time"
9	)
10	
11	// Clock 用于注入时间来源，主要服务于确定性测试；生产代码使用墙钟。
12	type Clock interface {
13		Now() time.Time
14	}
15	
16	type wallClock struct{}
17	
18	func (wallClock) Now() time.Time { return time.Now().UTC() }
19	
20	// Option 配置 [Open] 的行为。
21	type Option func(*Store)
22	
23	// WithClock 注入自定义时钟。
24	func WithClock(c Clock) Option {
25		return func(s *Store) { s.now = c.Now }
26	}
27	
28	// Store 是本地数值作业归档：负责提交、调度、取消、查询与持久化。
29	//
30	// 一次只运行一个作业；所有方法可被多个 goroutine 并发调用。
31	type Store struct {
32		dir string
33	
34		mu     sync.Mutex
35		jobs   []*storedJob // 严格按作业号（即提交先后）排列
36		byID   map[uint64]*storedJob
37		idem   map[string]uint64 // submitter\x00requestID -> 作业号
38		nextID uint64
39		closed bool
40	
41		now func() time.Time
42	
43		runningID uint64
44		waitCh    chan struct{}
45		stopCh    chan struct{}
46		stopping  atomic.Bool
47		wg        sync.WaitGroup
48	
49		// compute 仅用于包内确定性测试：若为空则使用真实的 [computeResult]。
50		// 必须在任何 Submit 之前（Open 之后立即）设置；worker 只会在收到
51		// Submit 的唤醒之后读取它，因此与设置之间存在 happens-before 关系。
52		compute func(id uint64, inputs []int64, seed int64, canceled func() bool) (sum, sumSquares int64, reason string, ok bool)
53	}
54	
55	// Open 打开（必要时创建）目录 dir 并恢复其中的全部作业记录。
56	//
57	// 恢复语义：
58	//   - 已确认的提交、取消与完成结果原样保留，幂等请求号继续生效；
59	//   - 上次关闭时仍在运行的作业标记为失败（计算被中断）并阻止其下游；
60	//   - 排队作业继续排队并由本地唯一 worker 按提交先后处理；
61	//   - 成功状态始终与完整归档同时可见。
62	func Open(dir string, opts ...Option) (*Store, error) {
63		if err := os.MkdirAll(dir, 0o700); err != nil {
64			return nil, err
65		}
66		jobs, maxID, err := loadDir(dir)
67		if err != nil {
68			return nil, err
69		}
70		s := &Store{
71			dir:    dir,
72			jobs:   jobs,
73			byID:   make(map[uint64]*storedJob),
74			idem:   make(map[string]uint64),
75			nextID: maxID + 1,
76			now:    wallClock{}.Now,
77			waitCh: make(chan struct{}, 1),
78			stopCh: make(chan struct{}),
79		}
80		for _, opt := range opts {
81			opt(s)
82		}
83		for _, j := range jobs {
84			s.byID[j.id] = j
85			if j.requestID != "" {
86				s.idem[s.idemKey(j.submitter, j.requestID)] = j.id
87			}
88		}
89		// 重建失败/取消作业对排队下游的阻断。
90		s.cascadeLocked()
91		s.wg.Add(1)
92		go s.worker()
93		return s, nil
94	}
95	
96	func (s *Store) idemKey(submitter, requestID string) string {
97		return submitter + "\x00" + requestID
98	}
99	
100	// Close 关闭归档。正在运行的作业会尽快中止并标记为失败（计算被中断），
101	// 排队作业原样保留在磁盘上，下次 [Open] 继续。
102	func (s *Store) Close() error {
103		s.mu.Lock()
104		if s.closed {
105			s.mu.Unlock()
106			return nil
107		}
108		s.closed = true
109		var running *storedJob
110		if s.runningID != 0 {
111			running = s.byID[s.runningID]
112		}
113		s.mu.Unlock()
114	
115		if s.stopping.CompareAndSwap(false, true) {
116			close(s.stopCh)
117		}
118		// 中止正在运行的计算。
119		if running != nil {
120			running.canceled.Store(true)
121		}
122		s.notify()
123		s.wg.Wait()
124		return nil
125	}
126	
127	// Submit 接受一次作业提交。
128	//
129	// 空序列返回 [ErrEmptySequence]；引用不存在的依赖返回
130	// [ErrDependencyNotFound]；同一提交人复用请求号但内容变化返回
131	// [ErrIdempotencyConflict]（同时返回原作业视图）——这些拒绝都不产生记录。
132	// 相同提交人+请求号+内容的重复提交（含并发重复）返回原作业及其当前状态。
133	func (s *Store) Submit(req SubmitRequest) (*Job, error) {
134		s.mu.Lock()
135		defer s.mu.Unlock()
136		if s.closed || s.stopping.Load() {
137			return nil, ErrStoreClosed
138		}
139		if len(req.Values) == 0 {
140			return nil, ErrEmptySequence
141		}
142		if err := s.validateDependenciesLocked(&req); err != nil {
143			return nil, err
144		}
145		deps := requestDeps(&req)
146		if req.RequestID != "" {
147			key := s.idemKey(req.Submitter, req.RequestID)
148			if origID, ok := s.idem[key]; ok {
149				orig := s.byID[origID]
150				if sameContent(orig, &req) {
151					return s.viewLocked(orig), nil
152				}
153				return s.viewLocked(orig),
154					fmt.Errorf("%w：提交人 %q 的请求号 %q 已用于作业 %d",
155						ErrIdempotencyConflict, req.Submitter, req.RequestID, origID)
156			}
157		}
158	
159		now := s.now().UTC()
160		j := &storedJob{
161			id:           s.nextID,
162			submitter:    req.Submitter,
163			requestID:    req.RequestID,
164			seed:         req.Seed,
165			values:       append([]int64(nil), req.Values...),
166			dependencies: append([]uint64(nil), deps...),
167			queuedAt:     now,
168			status:       StatusQueued,
169		}
170		// 先持久化，接受之后该提交即不可丢失。
171		if err := s.persist(j); err != nil {
172			return nil, err
173		}
174		s.nextID++
175		s.jobs = append(s.jobs, j)
176		s.byID[j.id] = j
177		if req.RequestID != "" {
178			s.idem[s.idemKey(req.Submitter, req.RequestID)] = j.id
179		}
180		// 依赖已失败/取消时，新接受的作业立刻进入失败终态。
181		s.cascadeLocked()
182		s.notifyLocked()
183		return s.viewLocked(j), nil
184	}
185	
186	// requestDeps 规范化一次提交的直接上游作业号列表：
187	// 非空 Dependencies 优先（保持次序）；否则单依赖方式退化为只含一个作业号的列表；
188	// 两者皆无则为 nil。调用前须先经 [Store.validateDependenciesLocked] 校验。
189	func requestDeps(req *SubmitRequest) []uint64 {
190		if len(req.Dependencies) > 0 {
191			return append([]uint64(nil), req.Dependencies...)
192		}
193		if req.HasDependency {
194			return []uint64{req.DependencyID}
195		}
196		return nil
197	}
198	
199	// validateDependenciesLocked 在持锁状态下校验提交的依赖列表：
200	//   - 单依赖方式与非空列表同时启用 → 拒绝；
201	//   - 列表含零或重复作业号 → 拒绝（错误指出具体作业号）；
202	//   - 列表引用提交时不存在的作业 → 拒绝。
203	//
204	// 任一拒绝都不产生记录，也不占用幂等请求号。
205	func (s *Store) validateDependenciesLocked(req *SubmitRequest) error {
206		if req.HasDependency && len(req.Dependencies) > 0 {
207			return fmt.Errorf("%w：单依赖方式与依赖列表不能同时启用", ErrInvalidDependency)
208		}
209		deps := requestDeps(req)
210		seen := make(map[uint64]struct{}, len(deps))
211		for _, id := range deps {
212			if id == 0 {
213				return fmt.Errorf("%w：依赖列表包含无效作业号 0", ErrInvalidDependency)
214			}
215			if _, dup := seen[id]; dup {
216				return fmt.Errorf("%w：依赖列表包含重复作业号 %d", ErrInvalidDependency, id)
217			}
218			seen[id] = struct{}{}
219		}
220		for _, id := range deps {
221			if s.byID[id] == nil {
222				return fmt.Errorf("%w：作业号 %d", ErrDependencyNotFound, id)
223			}
224		}
225		return nil
226	}
227	
228	// sameContent 判断两次提交的内容是否一致；整数次序或依赖列表（内容与次序）
229	// 不同即视为不同内容。单依赖方式与只含同一作业号的列表视为相同内容。
230	func sameContent(j *storedJob, req *SubmitRequest) bool {
231		if j.seed != req.Seed {
232			return false
233		}
234		rd := requestDeps(req)
235		if len(j.dependencies) != len(rd) {
236			return false
237		}
238		for i := range j.dependencies {
239			if j.dependencies[i] != rd[i] {
240				return false
241			}
242		}
243		if len(j.values) != len(req.Values) {
244			return false
245		}
246		for i := range j.values {
247			if j.values[i] != req.Values[i] {
248				return false
249			}
250		}
251		return true
252	}
253	
254	// Get 按作业号读取作业详情（含成功归档）；不存在返回 [ErrNotFound]。
255	func (s *Store) Get(id uint64) (*Job, error) {
256		s.mu.Lock()
257		defer s.mu.Unlock()
258		j := s.byID[id]
259		if j == nil {
260			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
261		}
262		return s.viewLocked(j), nil
263	}
264	
265	// Cancel 请求取消作业。
266	//
267	// 排队或运行中的作业都可以取消；取消一旦返回成功，该作业及依赖它的作业
268	// 都不会再产生成功归档。重复取消已取消的作业仍返回成功；对已成功或已
269	// 失败的作业取消返回 [ErrNotCancellable]，原结果保持不变。
270	func (s *Store) Cancel(id uint64) (*Job, error) {
271		s.mu.Lock()
272		defer s.mu.Unlock()
273		if s.closed {
274			return nil, ErrStoreClosed
275		}
276		j := s.byID[id]
277		if j == nil {
278			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
279		}
280		switch j.status {
281		case StatusCanceled:
282			return s.viewLocked(j), nil
283		case StatusSucceeded, StatusFailed:
284			return s.viewLocked(j),
285				fmt.Errorf("%w：作业 %d 当前状态为 %s", ErrNotCancellable, id, j.status)
286		}
287	
288		// queued / running：立刻把终态落盘，使“已确认的取消”不会因崩溃丢失。
289		now := s.now().UTC()
290		j.status = StatusCanceled
291		j.failureReason = ""
292		j.blockerID = 0
293		if j.finishedAt.IsZero() {
294			j.finishedAt = now
295		}
296		j.effectiveValues = nil
297		j.archive = nil
298		j.canceled.Store(true)
299		if err := s.persist(j); err != nil {
300			return nil, err
301		}
302		// 依赖它的等待者一并失败，且继续向更下游传播。
303		s.cascadeLocked()
304		s.notifyLocked()
305		return s.viewLocked(j), nil
306	}
307	
308	// List 按提交人和提交时间范围（两端均包含）列出记录，结果按提交先后排列。
309	// start 晚于 end 返回 [ErrInvalidTimeRange]。零值时间表示该端不限。
310	func (s *Store) List(submitter string, start, end time.Time) ([]*Job, error) {
311		s.mu.Lock()
312		defer s.mu.Unlock()
313		if !start.IsZero() && !end.IsZero() && start.After(end) {
314			return nil, fmt.Errorf("%w：起始时间 %s 晚于结束时间 %s",
315				ErrInvalidTimeRange, start.Format(time.RFC3339Nano), end.Format(time.RFC3339Nano))
316		}
317		out := make([]*Job, 0)
318		for _, j := range s.jobs { // jobs 已按 id 升序，即提交先后
319			if j.submitter != submitter {
320				continue
321			}
322			if !start.IsZero() && j.queuedAt.Before(start) {
323				continue
324			}
325			if !end.IsZero() && j.queuedAt.After(end) {
326				continue
327			}
328			out = append(out, s.viewLocked(j))
329		}
330		return out, nil
331	}
332	
333	// cascadeLocked 把“直接上游已失败/取消”的排队作业标记为失败并递归传播。
334	//
335	// 上游在提交时必须已存在，因此上游作业号必然更小，按作业号升序单趟
336	// 扫描即可让阻断沿链条传播到最下游。作业有多个直接上游时，按列表顺序
337	// 选取最靠前的已失败/取消者作为直接阻断者；作业一旦失败，其原因不再被
338	// 后来发生的上游状态变化改写。
339	func (s *Store) cascadeLocked() {
340		for _, j := range s.jobs {
341			if j.status != StatusQueued || len(j.dependencies) == 0 {
342				continue
343			}
344			var direct *storedJob
345			for _, id := range j.dependencies {
346				dep := s.byID[id]
347				if dep == nil {
348					continue
349				}
350				if dep.status == StatusFailed || dep.status == StatusCanceled {
351					direct = dep
352					break
353				}
354			}
355			if direct == nil {
356				continue
357			}
358			root := direct.blockerID
359			if root == 0 {
360				root = direct.id
361			}
362			s.markFailedLocked(j, blockedReason(direct, root), root)
363		}
364	}
365	
366	func blockedReason(dep *storedJob, root uint64) string {
367		state := "失败"
368		if dep.status == StatusCanceled {
369			state = "被取消"
370		}
371		reason := fmt.Sprintf("直接上游作业 %d 已%s，阻断本作业继续计算", dep.id, state)
372		if dep.status == StatusFailed && dep.failureReason != "" {
373			reason += "（其失败原因：" + dep.failureReason + "）"
374		}
375		if root != dep.id {
376			reason += fmt.Sprintf("；阻断根因为作业 %d", root)
377		}
378		return reason
379	}
380	
381	// pickRunnableLocked 返回提交顺序上第一个可运行的排队作业。
382	// 可运行要求全部直接上游都已成功并归档；只要还有一个上游在排队或运行，
383	// 该作业就被跳过，不挡住后面可运行的作业。
384	func (s *Store) pickRunnableLocked() *storedJob {
385		for _, j := range s.jobs {
386			if j.status != StatusQueued {
387				continue
388			}
389			if len(j.dependencies) == 0 {
390				return j
391			}
392			ready := true
393			for _, id := range j.dependencies {
394				dep := s.byID[id]
395				if dep == nil || dep.status != StatusSucceeded {
396					ready = false
397					break
398				}
399			}
400			if ready {
401				return j
402			}
403		}
404		return nil
405	}
406	
407	// notifyLocked 在持锁状态下非阻塞唤醒 worker。
408	func (s *Store) notifyLocked() {
409		select {
410		case s.waitCh <- struct{}{}:
411		default:
412		}
413	}
414	
415	// notify 在不持锁时唤醒 worker。
416	func (s *Store) notify() {
417		s.mu.Lock()
418		s.notifyLocked()
419		s.mu.Unlock()
420	}
421	
422	// persistRetry 对落盘做有限次重试，尽量避免内存状态与磁盘记录分叉。
423	func (s *Store) persistRetry(j *storedJob, attempts int) error {
424		var err error
425		for i := 0; i < attempts; i++ {
426			if err = s.persist(j); err == nil {
427				return nil
428			}
429		}
430		return err
431	}
432	
433	// worker 是本地唯一的计算执行体。
434	func (s *Store) worker() {
435		defer s.wg.Done()
436		for {
437			s.mu.Lock()
438			if s.stopping.Load() {
439				s.mu.Unlock()
440				return
441			}
442			j := s.pickRunnableLocked()
443			if j == nil {
444				ch := s.waitCh
445				s.mu.Unlock()
446				select {
447				case <-ch:
448				case <-s.stopCh:
449				}
450				continue
451			}
452	
453			// 进入运行并原子持久化该状态。
454			j.status = StatusRunning
455			j.startedAt = s.now().UTC()
456			// 实际输入 = 原始序列 + 各直接上游的总和（严格按列表顺序追加）。
457			inputs := append([]int64(nil), j.values...)
458			for _, id := range j.dependencies {
459				if dep := s.byID[id]; dep != nil && dep.archive != nil {
460					inputs = append(inputs, dep.archive.Sum)
461				}
462			}
463			seed := j.seed
464			s.runningID = j.id
465			if err := s.persistRetry(j, 3); err != nil {
466				// 连运行状态都无法落盘：保守地失败，不进行计算。
467				s.markFailedLocked(j, "无法持久化作业状态："+err.Error(), 0)
468				s.runningID = 0
469				s.cascadeLocked()
470				s.notifyLocked()
471				s.mu.Unlock()
472				continue
473			}
474			s.mu.Unlock()
475	
476			abort := func() bool { return j.canceled.Load() || s.stopping.Load() }
477			doCompute := s.compute
478			if doCompute == nil {
479				doCompute = func(_ uint64, in []int64, sd int64, c func() bool) (int64, int64, string, bool) {
480					return computeResult(in, sd, c)
481				}
482			}
483			sum, sumSq, reason, ok := doCompute(j.id, inputs, seed, abort)
484	
485			s.mu.Lock()
486			s.runningID = 0
487			switch {
488			case j.status == StatusCanceled:
489				// 用户取消已在 Cancel 中落盘；此处确保丢弃任何计算产物。
490				j.archive = nil
491				j.effectiveValues = nil
492				_ = s.persistRetry(j, 3)
493				s.cascadeLocked()
494			case s.stopping.Load():
495				s.markFailedLocked(j, "计算被中断：归档在计算过程中关闭", 0)
496				s.cascadeLocked()
497			case !ok:
498				s.markFailedLocked(j, reason, 0)
499				s.cascadeLocked()
500			default:
501				// 成功：状态与完整归档在同一条记录的同一次原子写入中可见。
502				completed := s.now().UTC()
503				a := newArchive(j, inputs, sum, sumSq, completed)
504				j.effectiveValues = append([]int64(nil), inputs...)
505				j.status = StatusSucceeded
506				j.finishedAt = completed
507				j.failureReason = ""
508				j.blockerID = 0
509				j.archive = a
510				if err := s.persistRetry(j, 3); err != nil {
511					// 落盘失败时绝不让对外可见“成功却没有归档”：回退为失败。
512					j.archive = nil
513					j.effectiveValues = nil
514					s.markFailedLocked(j, "结果归档写入失败："+err.Error(), 0)
515				}
516			}
517			s.notifyLocked()
518			s.mu.Unlock()
519		}
520	}
521	
522	// markFailedLocked 在持锁状态下把作业置为失败终态并尝试落盘。
523	func (s *Store) markFailedLocked(j *storedJob, reason string, blocker uint64) {
524		j.status = StatusFailed
525		j.failureReason = reason
526		j.blockerID = blocker
527		if j.finishedAt.IsZero() {
528			j.finishedAt = s.now().UTC()
529		}
530		j.archive = nil
531		j.effectiveValues = nil
532		_ = s.persistRetry(j, 3)
533	}
534	
535	// newArchive 构造成功归档；CompletedAt 之外的全部字段都是确定性的。
536	// 上游作业号只作记录，不参与任何摘要与校验值。
537	func newArchive(j *storedJob, effective []int64, sum, sumSquares int64, completedAt time.Time) *Archive {
538		inDigest := inputsDigestHex(effective, j.seed)
539		resDigest := resultDigestHex(effective, j.seed, sum, sumSquares)
540		log := buildLog(effective, j.seed, sum, sumSquares)
541		checksum := checksumHex(effective, j.seed, sum, sumSquares, log, resDigest)
542		var firstDep uint64
543		if len(j.dependencies) > 0 {
544			firstDep = j.dependencies[0]
545		}
546		return &Archive{
547			JobID:           j.id,
548			Submitter:       j.submitter,
549			RequestID:       j.requestID,
550			Seed:            j.seed,
551			Values:          append([]int64(nil), j.values...),
552			HasDependency:   len(j.dependencies) > 0,
553			DependencyID:    firstDep,
554			Dependencies:    append([]uint64(nil), j.dependencies...),
555			EffectiveValues: append([]int64(nil), effective...),
556			InputsDigest:    inDigest,
557			Sum:             sum,
558			SumOfSquares:    sumSquares,
559			ResultDigest:    resDigest,
560			Log:             log,
561			Checksum:        checksum,
562			CompletedAt:     completedAt,
563		}
564	}
565	
566	// viewLocked 在持锁状态下生成对外只读视图，全部切片深拷贝。
567	func (s *Store) viewLocked(j *storedJob) *Job {
568		v := &Job{
569			ID:              j.id,
570			Submitter:       j.submitter,
571			RequestID:       j.requestID,
572			Seed:            j.seed,
573			Values:          append([]int64(nil), j.values...),
574			Dependencies:    append([]uint64(nil), j.dependencies...),
575			QueuedAt:        j.queuedAt,
576			StartedAt:       j.startedAt,
577			FinishedAt:      j.finishedAt,
578			Status:          j.status,
579			FailureReason:   j.failureReason,
580			BlockerID:       j.blockerID,
581			EffectiveValues: append([]int64(nil), j.effectiveValues...),
582		}
583		v.HasDependency = len(j.dependencies) > 0
584		if len(j.dependencies) > 0 {
585			v.DependencyID = j.dependencies[0]
586		}
587		if j.status == StatusQueued {
588			v.WaitReason = WaitSlot
589			// 列出尚未成功归档的直接上游，保持提交时的顺序。
590			for _, id := range j.dependencies {
591				if dep := s.byID[id]; dep == nil || dep.status != StatusSucceeded {
592					v.PendingDependencies = append(v.PendingDependencies, id)
593				}
594			}
595			if len(v.PendingDependencies) > 0 {
596				v.WaitReason = WaitDependency
597			}
598		}
599		if j.archive != nil {
600			a := *j.archive
601			a.Values = append([]int64(nil), j.archive.Values...)
602			a.EffectiveValues = append([]int64(nil), j.archive.EffectiveValues...)
603			a.Dependencies = append([]uint64(nil), j.archive.Dependencies...)
604			v.Archive = &a
605		}
606		return v
607	}
608	
609	// Dir 返回归档目录路径。
610	func (s *Store) Dir() string { return s.dir }
611

