1	package numeric
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"path/filepath"
8		"sort"
9		"strings"
10		"sync/atomic"
11		"time"
12	)
13	
14	// recordVersion 是落盘记录格式的版本标记。
15	const recordVersion = "numeric-job-v1"
16	
17	// storedJob 是作业在内存中的完整状态，所有字段均由 Store.mu 保护。
18	type storedJob struct {
19		id           uint64
20		submitter    string
21		requestID    string
22		seed         int64
23		values       []int64
24		dependencies []uint64 // 有序直接上游作业号；空表示无依赖
25	
26		queuedAt   time.Time
27		startedAt  time.Time
28		finishedAt time.Time
29	
30		status        Status
31		failureReason string
32		blockerID     uint64
33	
34		// 成功后保存的有效输入与归档（与 succeeded 状态同一次原子写入）。
35		effectiveValues []int64
36		archive         *Archive
37	
38		// canceled 仅存于内存：运行中的作业收到取消/关闭请求后置位，
39		// 计算循环据此尽快中止；终态不会依赖它落盘（终态本身会持久化）。
40		canceled atomic.Bool
41	}
42	
43	// jobRecord 是 storedJob 的落盘 JSON 表示。成功状态与归档在同一记录内，
44	// 一次 temp-file + rename 原子写入，因此对外不会出现“成功却没有结果”。
45	type jobRecord struct {
46		Version string `json:"version"`
47	
48		ID            uint64  `json:"id"`
49		Submitter     string  `json:"submitter"`
50		RequestID     string  `json:"request_id"`
51		Seed          int64   `json:"seed"`
52		Values        []int64 `json:"values"`
53		HasDependency bool    `json:"has_dependency"`
54		DependencyID  uint64  `json:"dependency_id"`
55		// Dependencies 为有序直接上游作业号；旧格式记录无此字段，
56		// 恢复时由 HasDependency/DependencyID 推导。
57		Dependencies []uint64 `json:"dependencies,omitempty"`
58	
59		QueuedAt   time.Time `json:"queued_at"`
60		StartedAt  time.Time `json:"started_at,omitempty"`
61		FinishedAt time.Time `json:"finished_at,omitempty"`
62	
63		Status        Status `json:"status"`
64		FailureReason string `json:"failure_reason,omitempty"`
65		BlockerID     uint64 `json:"blocker_id,omitempty"`
66	
67		EffectiveValues []int64  `json:"effective_values,omitempty"`
68		Archive         *Archive `json:"archive,omitempty"`
69	}
70	
71	func jobFileName(id uint64) string {
72		return fmt.Sprintf("job-%020d.json", id)
73	}
74	
75	func (s *Store) jobPath(j *storedJob) string {
76		return filepath.Join(s.dir, jobFileName(j.id))
77	}
78	
79	func encodeRecord(j *storedJob) ([]byte, error) {
80		r := jobRecord{
81			Version: recordVersion,
82	
83			ID:            j.id,
84			Submitter:     j.submitter,
85			RequestID:     j.requestID,
86			Seed:          j.seed,
87			Values:        append([]int64(nil), j.values...),
88			HasDependency: len(j.dependencies) > 0,
89			DependencyID:  depID(j),
90			Dependencies:  append([]uint64(nil), j.dependencies...),
91	
92			QueuedAt:      j.queuedAt,
93			StartedAt:     j.startedAt,
94			FinishedAt:    j.finishedAt,
95			Status:        j.status,
96			FailureReason: j.failureReason,
97			BlockerID:     j.blockerID,
98	
99			EffectiveValues: append([]int64(nil), j.effectiveValues...),
100			Archive:         j.archive,
101		}
102		return json.MarshalIndent(&r, "", "  ")
103	}
104	
105	// depID 返回首个直接上游作业号（无依赖时为 0）。
106	func depID(j *storedJob) uint64 {
107		if len(j.dependencies) == 0 {
108			return 0
109		}
110		return j.dependencies[0]
111	}
112	
113	// persist 在已持锁的情况下原子写一条作业记录。
114	func (s *Store) persist(j *storedJob) error {
115		data, err := encodeRecord(j)
116		if err != nil {
117			return err
118		}
119		return writeFileAtomic(s.dir, jobFileName(j.id), data, 0o600)
120	}
121	
122	// writeFileAtomic 将 data 写入 dir/name：同目录临时文件 → fsync → rename
123	// → 目录 fsync，保证记录要么是旧内容要么是新内容，不会出现半条记录。
124	func writeFileAtomic(dir, name string, data []byte, perm os.FileMode) error {
125		tmp, err := os.CreateTemp(dir, ".tmp-"+name+".*")
126		if err != nil {
127			return err
128		}
129		tmpName := tmp.Name()
130		cleanup := true
131		defer func() {
132			if cleanup {
133				_ = os.Remove(tmpName)
134			}
135		}()
136	
137		if _, err := tmp.Write(data); err != nil {
138			_ = tmp.Close()
139			return err
140		}
141		if err := tmp.Sync(); err != nil {
142			_ = tmp.Close()
143			return err
144		}
145		if err := tmp.Close(); err != nil {
146			return err
147		}
148		if err := os.Chmod(tmpName, perm); err != nil {
149			return err
150		}
151		if err := os.Rename(tmpName, filepath.Join(dir, name)); err != nil {
152			return err
153		}
154		cleanup = false
155		syncDir(dir)
156		return nil
157	}
158	
159	// syncDir 对目录本身做一次 fsync，让新建项与 rename 在崩溃后仍然成立。
160	func syncDir(dir string) {
161		if d, err := os.Open(dir); err == nil {
162			_ = d.Sync()
163			_ = d.Close()
164		}
165	}
166	
167	// loadDir 扫描目录中的全部作业记录并重建内存索引。
168	//
169	// 恢复规则：
170	//   - 上次关闭时仍为 running 的作业标记为失败，原因是计算被中断；
171	//   - 成功记录缺少归档或校验值对不上时 fail-closed 地标记为失败，
172	//     维持“成功必有完整归档”的不变量。
173	func loadDir(dir string) ([]*storedJob, uint64, error) {
174		entries, err := os.ReadDir(dir)
175		if err != nil {
176			return nil, 0, err
177		}
178		var jobs []*storedJob
179		var maxID uint64
180		for _, e := range entries {
181			name := e.Name()
182			if e.IsDir() {
183				continue
184			}
185			// 清理上一进程崩溃时可能残留的原子写临时文件。
186			if strings.HasPrefix(name, ".tmp-") {
187				_ = os.Remove(filepath.Join(dir, name))
188				continue
189			}
190			if !strings.HasPrefix(name, "job-") || !strings.HasSuffix(name, ".json") {
191				continue
192			}
193			path := filepath.Join(dir, name)
194			data, err := os.ReadFile(path)
195			if err != nil {
196				return nil, 0, err
197			}
198			var r jobRecord
199			if err := json.Unmarshal(data, &r); err != nil {
200				return nil, 0, fmt.Errorf("numeric: 记录 %s 损坏: %w", name, err)
201			}
202			if r.Version != recordVersion {
203				return nil, 0, fmt.Errorf("numeric: 记录 %s 版本不受支持: %s", name, r.Version)
204			}
205			switch r.Status {
206			case StatusQueued, StatusRunning, StatusSucceeded, StatusFailed, StatusCanceled:
207			default:
208				return nil, 0, fmt.Errorf("numeric: 记录 %s 状态非法: %q", name, r.Status)
209			}
210			// 新格式记录直接给出有序依赖列表；旧格式记录只有单依赖字段，
211			// 恢复为只含一个作业号的列表（语义与提交时一致）。
212			deps := append([]uint64(nil), r.Dependencies...)
213			if len(deps) == 0 && r.HasDependency {
214				deps = []uint64{r.DependencyID}
215			}
216			j := &storedJob{
217				id:           r.ID,
218				submitter:    r.Submitter,
219				requestID:    r.RequestID,
220				seed:         r.Seed,
221				values:       append([]int64(nil), r.Values...),
222				dependencies: deps,
223	
224				queuedAt:   r.QueuedAt,
225				startedAt:  r.StartedAt,
226				finishedAt: r.FinishedAt,
227	
228				status:        r.Status,
229				failureReason: r.FailureReason,
230				blockerID:     r.BlockerID,
231	
232				effectiveValues: append([]int64(nil), r.EffectiveValues...),
233				archive:         r.Archive,
234			}
235			if j.status == StatusRunning {
236				j.status = StatusFailed
237				j.failureReason = "计算被中断：归档上次关闭时作业仍在运行"
238				j.blockerID = 0
239				if j.finishedAt.IsZero() {
240					j.finishedAt = time.Now().UTC()
241				}
242				j.effectiveValues = nil
243				j.archive = nil
244				// 就地重写恢复后的终态。
245				if data, err := encodeRecord(j); err == nil {
246					_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
247				}
248			}
249			if j.status == StatusSucceeded && !archiveIntact(j) {
