545		}
546		if !strings.Contains(f.FailureReason, "作业") || !strings.Contains(m.FailureReason, "阻断") {
547			t.Fatalf("failure reasons must identify blocker: mid=%q far=%q", m.FailureReason, f.FailureReason)
548		}
