		t.Fatalf("cancel running: %+v %v", cj, err)
	}
	if g, _ := s.Get(run.ID); g.Status != StatusCanceled || g.FinishedAt.IsZero() {
		t.Fatalf("query right after confirmed cancel: %+v", g)
